(function(){
  const pages=['Membership tiers'];
  const definitions={builder:{name:'Builder / managing contractor',description:'For businesses managing the build, coordinating trades and maintaining the overall programme.',features:['Build-package tender categories','Trade coordination and project management workspace','Scope progress, valuation and invoice drafts']},trade:{name:'Trade subcontractor',description:'For practitioners pricing and delivering their own trade scope within a project.',features:['Trade-specific tender categories','Own-scope progress and document workspace','Trade pricing and invoice drafts']},supplyOnly:{name:'Supply-only supplier',description:'For product suppliers managing their own quotes, orders and supply scope.',features:['Product and supply tender categories','Own-scope product quotes and delivery information','Supply pricing and invoice drafts']}};
  const money=n=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
  function setup(c){if(!c.store.membershipTierProposals)c.store.membershipTierProposals={builder:149,trade:99,supplyOnly:49,gstRate:15,status:'Proposal — not approved'};if(!Array.isArray(c.store.membershipTierInterests))c.store.membershipTierInterests=[];if(!Array.isArray(c.store.contractorTenderProfiles))c.store.contractorTenderProfiles=[];return c.store.membershipTierProposals;}
  const validRate=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=10000;
  function render(page,c){const proposed=setup(c),e=c.escape,gst=validRate(proposed.gstRate)?proposed.gstRate:15,baseline=c.store.fees?.contractorMonthly;return `<div class="shm-workspace"><div class="heading"><div><div class="eyebrow">TENDER MARKETPLACE / PROPOSED MEMBERSHIP</div><h1>Membership tiers</h1><p>Match marketplace membership to the work your business delivers.</p></div></div><section class="card shm-notice"><h2>Suggested monthly rates for review</h2><p>These are product proposals, not market-validated rates or approved billing. ${validRate(baseline)?`The existing configured contractor monthly fee remains ${money(baseline)} excluding GST.`:'No existing configured fee is changed.'} Choosing interest below does not activate a subscription, charge payment or bind terms.</p><span class="tag amber">${e(proposed.status || 'Proposal — not approved')}</span></section><div class="shm-tiers">${Object.entries(definitions).map(([key,t])=>{const price=proposed[key],valid=validRate(price);return `<section class="card"><span class="eyebrow">${key==='builder'?'MANAGE THE BUILD':key==='trade'?'DELIVER YOUR TRADE':'SUPPLY YOUR PRODUCTS'}</span><h2>${e(t.name)}</h2><h3>${valid?`${money(price)} / month`:'Rate requires review'}</h3><p>${valid?`${money(Math.round(price*(1+gst/100)*100)/100)} including ${gst}% GST · monthly price excluding GST above`:''}</p><p>${e(t.description)}</p><ul>${t.features.map(x=>`<li>${e(x)}</li>`).join('')}</ul><button class="secondary" data-shm-tier="${key}" ${!valid?'disabled':''}>Select signup interest</button></section>`;}).join('')}</div><section class="card"><h2>Overlapping business roles</h2><p>A business may be a builder, a trade subcontractor and a product supplier. Proposed policy: use the highest applicable tier when the business manages a build; otherwise match the scope offered. Eligibility, exceptions and the final policy are negotiable and require approval. This demo does not automatically enforce or upgrade a tier.</p><p>All proposed tiers include eligible invitations, pricing and draft invoices for their own scope. Invitation eligibility depends on trade and project fit, not a guaranteed number of leads. Production access must enforce contractor cost privacy and project permissions on the server; role screens and NDAs alone do not secure data.</p></section>${c.role==='contractor'?`<form class="card shm-form" id="shm-interest"><h2>Record your business interest</h2><label>Business name<input name="business" required maxlength="160"></label><label>NZBN (optional)<input name="nzbn" inputmode="numeric" pattern="[0-9]{13}" maxlength="13"><span class="small">13-digit format check only; this does not verify a business.</span></label><label>Proposed tier<select name="tier" id="shm-tier">${Object.entries(definitions).map(([key,t])=>`<option value="${key}">${e(t.name)}</option>`).join('')}</select></label><label>Primary tender role<select name="tenderRole"><option value="builder">Builder / managing contractor</option><option value="trade">Trade subcontractor</option><option value="supplyOnly">Supply-only supplier</option></select></label><label>Trade or product category<input name="tradeType" required maxlength="120" placeholder="e.g. carpentry, electrical, windows"></label><label class="shm-check"><input name="proposalReviewed" type="checkbox" required> I understand this is signup interest in a proposal; no payment or binding terms apply.</label><button class="primary">Save interest</button></form>`:'<section class="card"><p>Contractors can record signup interest from their role preview. Staff can review these proposals without approving or changing the existing fee.</p></section>'}<section class="card"><h2>Recorded signup interests</h2>${c.store.membershipTierInterests.map(x=>`<article class="shm-interest"><strong>${e(x.business)}</strong><p>${e(definitions[x.tier]?.name || x.tier)} · ${money(x.priceSnapshot)} excluding GST · ${e(x.status)}<br>Saved ${e(x.createdAt)}${x.nzbn?` · NZBN ${e(x.nzbn)} (unverified)`:''}</p></article>`).join('') || '<p>No tier signup interests recorded yet.</p>'}</section></div>`;}
  function bind(page,c){const proposed=setup(c),root=document.querySelector('.shm-workspace');if(!root)return;const form=root.querySelector('#shm-interest');root.querySelectorAll('[data-shm-tier]').forEach(b=>b.onclick=()=>{if(!form)return c.toast('Record interest from the contractor role preview.');form.elements.tier.value=b.dataset.shmTier;form.elements.tenderRole.value=b.dataset.shmTier;form.scrollIntoView({behavior:'smooth',block:'start'});});if(form)form.onsubmit=ev=>{ev.preventDefault();if(c.role!=='contractor')return;const d=Object.fromEntries(new FormData(form)),price=proposed[d.tier],gst=proposed.gstRate;if(!definitions[d.tier]||!definitions[d.tenderRole]||!validRate(price)||!validRate(gst)||!d.business.trim()||!d.tradeType.trim()||!d.proposalReviewed||(d.nzbn&&!/^\d{13}$/.test(d.nzbn)))return c.toast('Check business, optional NZBN format, tier and review checkbox.');const createdAt=new Date().toISOString(),id='tier-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);c.store.membershipTierInterests.push({id,business:d.business.trim(),nzbn:d.nzbn,tier:d.tier,priceSnapshot:price,gstRate:gst,status:'Interest only',createdAt,...(c.projectId?{projectId:c.projectId}:{})});c.store.contractorTenderProfiles.push({id,business:d.business.trim(),nzbn:d.nzbn,tenderRole:d.tenderRole,tradeType:d.tradeType.trim(),verificationStatus:'Self-declared — unverified',createdAt});c.save();if(c.notify)c.notify({title:'Proposed membership tier interest',message:d.business+' registered interest; no subscription activated.',roles:['staff'],kind:'membership'});c.toast('Tier interest saved; existing contractor fee unchanged');c.navigate(page);};}
  window.SHMembership={pages,render,bind};
})();
